-- Minimal dependencies for isolated PostgreSQL policy tests, NOT managed services.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema storage;
create schema extensions;
grant usage on schema public,auth,storage,extensions to anon,authenticated,service_role;
alter default privileges in schema public grant all on tables to anon,authenticated,service_role;
alter default privileges in schema public grant all on sequences to anon,authenticated,service_role;
create table auth.users(id uuid primary key,email text,raw_user_meta_data jsonb default '{}');
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text);
alter table storage.objects enable row level security;
create function storage.foldername(text) returns text[] language sql immutable as $$select (string_to_array($1,'/'))[1:array_length(string_to_array($1,'/'),1)-1]$$;
create function extensions.ok(value boolean,label text) returns text language plpgsql as $$begin if value is distinct from true then raise exception 'Assertion failed: %',label; end if;return 'ok: '||label;end$$;
create function extensions.is(actual anyelement,expected anyelement,label text) returns text language plpgsql as $$begin if actual is distinct from expected then raise exception 'Assertion failed: %',label;end if;return 'ok: '||label;end$$;
create function extensions.no_plan() returns text language sql as $$select 'standalone assertions'::text$$;
create function extensions.finish() returns text language sql as $$select 'finished'::text$$;
create function extensions.lives_ok(statement text,label text) returns text language plpgsql as $$begin execute statement;return 'ok: '||label;end$$;
create function extensions.throws_ok(statement text,expected_state text,expected_message text,label text) returns text language plpgsql as $$declare caught_state text;caught_message text;begin begin execute statement;exception when others then get stacked diagnostics caught_state=returned_sqlstate,caught_message=message_text;end;if caught_state is distinct from expected_state or(expected_message is not null and caught_message is distinct from expected_message)then raise exception 'Assertion failed: %, expected %, got %',label,expected_state,caught_state;end if;return 'ok: '||label;end$$;
grant execute on all functions in schema extensions to anon,authenticated;
